// ============================================================
//  ⚙️ CONFIG: the only node you need to edit
// ============================================================
return [{
  json: {
    // Google Sheet ID: the long string in the URL between /d/ and /edit
    // Google Sheet ID: the long string in the sheet's URL between /d/ and /edit
    sheet_id: 'YOUR_GOOGLE_SHEET_ID',
    // Tab ID: the number after #gid= in the sheet's URL. Survives renaming the tab.
    // (A sheet created from a CSV import does NOT get gid 0; copy it from the URL.)
    sheet_gid: '0',

    // Who gets the weekly email (comma separated)
    report_to: 'YOUR_EMAIL@example.com',

    restaurant_name: 'بيت الصاج',
    // Language model, through the OpenAI-compatible chat API.
    // Credential: "Header Auth" with Name = Authorization, Value = Bearer <your key>.
    //   FREE  · Google Gemini (key from aistudio.google.com/apikey):
    llm_url: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
    model: 'gemini-2.5-flash',
    //   PAID  · OpenAI: llm_url 'https://api.openai.com/v1/chat/completions', model 'gpt-4.1-mini'

    // Week window. reference_date = "today" for the filter.
    //   DEMO: '2026-11-22' → reads the demo week 15–21 Nov 2026
    //   PRODUCTION: '' → uses the real date when the Schedule fires
    reference_date: '2026-11-22',
    lookback_days: 7,

    // Shift split: visits before this hour = lunch (غداء), after = evening (مسائي)
    evening_starts_at_hour: 16,
    // Jordan weekend = Friday (5) + Saturday (6)
    weekend_days: [5, 6],

    // Closed list of dishes → the model can't invent new dish names,
    // so "شاورما" and "ساندويش شاورما دجاج" end up in the same bucket.
    menu: ['شاورما', 'فلافل', 'حمص', 'فتة', 'منسف', 'مشاوي مشكلة', 'كبة', 'فتوش', 'بطاطا', 'خبز', 'كنافة', 'عصائر'],
  },
}];

// Filter this week's reviews, compute the shift FROM THE DATA (not from the model),
// and build one OpenAI Structured Output request per review.
const cfg = $('Config').first().json;

// OpenAI's strict mode needs additionalProperties:false on every object; Gemini's
// OpenAI-compatible endpoint is happier without it. The code validates the answer either way.
const STRICT = /api\.openai\.com/.test(cfg.llm_url);
function lock(schema) {
  if (!STRICT || !schema || typeof schema !== 'object') return schema;
  const s = { ...schema };
  if (s.type === 'object') s.additionalProperties = false;
  if (s.properties) s.properties = Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, lock(v)]));
  if (s.items) s.items = lock(s.items);
  return s;
}

const DAYS_AR = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
const ISSUE_TYPES = [
  'cold_food', 'taste_quality', 'portion_size', 'hygiene', 'wait_time', 'delivery_delay',
  'order_accuracy', 'packaging', 'staff_behavior', 'price', 'ambience', 'other', 'none',
];

// Sheets may return a date as a serial number (auto-detected) or as text.
// All times are handled as "wall clock" via UTC methods, so no timezone shift.
function parseWallClock(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return new Date(Date.UTC(1899, 11, 30) + Math.round(v * 86400000));
  const m = String(v).trim().match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2}):(\d{2}))?/);
  if (!m) return null;
  return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3], +(m[4] || 0), +(m[5] || 0)));
}

function todayWallClock() {
  if (cfg.reference_date) return parseWallClock(cfg.reference_date);
  // $now is a Luxon DateTime in the workflow timezone (Asia/Amman)
  return new Date(Date.UTC($now.year, $now.month - 1, $now.day));
}

const end = todayWallClock();                                   // exclusive
const start = new Date(end.getTime() - cfg.lookback_days * 86400000);
const fmt = (d) => d.toISOString().slice(0, 10);

const systemPrompt = `You classify restaurant reviews for the kitchen and floor managers of "${cfg.restaurant_name}" (Amman, Jordan).
Reviews may be in Modern Standard Arabic, Levantine/Jordanian dialect, or English.

Return ONLY the JSON defined by the schema. Rules:
- dish: the menu item the review is mainly about. Use "عام" when the point is not about a specific dish (delivery, staff, wait, ambience, general praise). Use "غير محدد" only if a dish is clearly meant but cannot be identified. A "ساندويش" in a shawarma context is "شاورما".
- issue_type: the PRIMARY problem. "none" if the review has no complaint at all.
  cold_food = food served cold/lukewarm. delivery_delay = late delivery (even if the food arrived cold because of it). wait_time = slow service or crowding in the restaurant.
- severity (0-5): 0 = no problem. 1 = minor remark inside a positive review. 2 = noticeable problem. 3 = clear failure that spoiled part of the meal. 4 = ruined the visit / customer says they won't return. 5 = health or safety (hair, foreign object, food poisoning, allergen).
- sentiment: overall tone.
- summary: Arabic, max 12 words, factual, no exaggeration.
- reply_draft: ONLY if the review contains a complaint or the rating is 3 or less; otherwise "". Same language as the review (dialect → warm, clear Arabic). Max 60 words. Thank them, acknowledge the specific issue, say what will be checked. Never promise refunds or free meals, never blame the customer, never invent facts. Sign as "${cfg.restaurant_name}".`;

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r.review_id || !String(r.review_text || '').trim()) continue;

  const visit = parseWallClock(r.visit_datetime) || parseWallClock(r.review_date);
  if (!visit || visit < start || visit >= end) continue;

  const dow = visit.getUTCDay();
  const part = visit.getUTCHours() < cfg.evening_starts_at_hour ? 'غداء' : 'مسائي';

  const row = {
    review_id: String(r.review_id),
    visit_date: fmt(visit),
    visit_hour: visit.getUTCHours(),
    weekday: dow,
    shift: `${DAYS_AR[dow]} · ${part}`,
    week_part: cfg.weekend_days.includes(dow) ? 'الويكند' : 'أيام الدوام',
    source: r.source || '',
    rating: Number(r.rating) || null,
    reviewer: r.reviewer || '',
    review_text: String(r.review_text).trim(),
  };

  row.openai_body = {
    model: cfg.model,
    temperature: 0,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `Rating: ${row.rating ?? 'n/a'}/5\nSource: ${row.source}\nReview:\n${row.review_text}` },
    ],
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'review_classification',
        strict: STRICT,
        schema: lock({
          type: 'object',
          required: ['dish', 'issue_type', 'severity', 'sentiment', 'summary', 'reply_draft'],
          properties: {
            dish: { type: 'string', enum: [...cfg.menu, 'عام', 'غير محدد'] },
            issue_type: { type: 'string', enum: ISSUE_TYPES },
            severity: { type: 'integer', description: '0 to 5' },
            sentiment: { type: 'string', enum: ['positive', 'mixed', 'negative'] },
            summary: { type: 'string' },
            reply_draft: { type: 'string' },
          },
        }),
      },
    },
  };
  out.push({ json: row });
}

// Keep the window on every item so later nodes (and the email) can show it.
const window = { from: fmt(start), to: fmt(new Date(end.getTime() - 86400000)) };
return out.map((o) => ({ json: { ...o.json, week: window } }));

// Join each OpenAI response back to its review (same order, 1:1) and validate it.
// Anything the model returns that breaks the rules is corrected here, in code.
const reviews = $('Prepare week').all();
const responses = $input.all();
if (reviews.length !== responses.length) {
  throw new Error(`Got ${responses.length} classifications for ${reviews.length} reviews`);
}

const classifiedAt = $now.toFormat('yyyy-MM-dd HH:mm');
const cfg = $('Config').first().json;
const DISHES = new Set([...cfg.menu, 'عام', 'غير محدد']);
const ISSUES = new Set(['cold_food', 'taste_quality', 'portion_size', 'hygiene', 'wait_time', 'delivery_delay',
  'order_accuracy', 'packaging', 'staff_behavior', 'price', 'ambience', 'other', 'none']);

return reviews.map((rev, i) => {
  const { openai_body, ...row } = rev.json;
  const res = responses[i].json;
  let c = null;
  let needs_review = false;

  try {
    const msg = res.choices[0].message;
    if (msg.refusal) throw new Error('refusal');
    c = JSON.parse(msg.content);
  } catch (e) {
    needs_review = true;
    c = { dish: 'غير محدد', issue_type: 'other', severity: 2, sentiment: 'mixed',
          summary: 'تعذّر التصنيف تلقائياً، راجعها يدوياً', reply_draft: '' };
  }

  // Values outside the lists are corrected here, whichever model answered
  if (!needs_review) {
    if (!DISHES.has(c.dish)) c.dish = 'غير محدد';
    if (!ISSUES.has(c.issue_type)) { c.issue_type = 'other'; needs_review = true; }
    c.severity = Math.max(0, Math.min(5, Math.round(Number(c.severity) || 0)));
    c.summary = String(c.summary || '');
    c.reply_draft = String(c.reply_draft || '');
  }

  // Consistency rules
  if (c.issue_type === 'none') c.severity = 0;
  if (c.issue_type !== 'none' && c.severity === 0) c.severity = 1;

  const is_issue = c.issue_type !== 'none';
  const is_negative = (row.rating !== null && row.rating <= 3) || c.severity >= 3;

  return {
    json: {
      ...row,
      dish: c.dish,
      issue_type: c.issue_type,
      severity: c.severity,
      sentiment: c.sentiment,
      summary: c.summary,
      reply_draft: is_negative || is_issue ? c.reply_draft : '',
      is_issue,
      is_negative,
      needs_review,
      classified_at: classifiedAt,
      tokens: res.usage ? res.usage.total_tokens : null,
    },
  };
});

// Only the columns we write back to the sheet. review_id is the match key.
const ISSUE_AR = {
  cold_food: 'أكل بارد', taste_quality: 'طعم/جودة', portion_size: 'الكمية', hygiene: 'نظافة',
  wait_time: 'انتظار', delivery_delay: 'تأخير توصيل', order_accuracy: 'غلط بالطلب',
  packaging: 'تغليف', staff_behavior: 'تعامل الموظفين', price: 'السعر', ambience: 'الأجواء',
  other: 'أخرى', none: 'لا يوجد',
};

return $input.all().map(({ json: r }) => ({
  json: {
    review_id: r.review_id,
    dish: r.dish,
    shift: r.shift,
    issue_type: ISSUE_AR[r.issue_type] || r.issue_type,
    severity: r.severity,
    summary: r.needs_review ? `⚠️ ${r.summary}` : r.summary,
    reply_draft: r.reply_draft,
    classified_at: r.classified_at,
  },
}));

// Counting happens HERE in code, not inside the model.
// The model only receives the finished numbers and turns them into decisions.
const cfg = $('Config').first().json;
const rows = $('Parse classification').all().map((i) => i.json);

// OpenAI's strict mode needs additionalProperties:false on every object; Gemini's
// OpenAI-compatible endpoint is happier without it. The code validates the answer either way.
const STRICT = /api\.openai\.com/.test(cfg.llm_url);
function lock(schema) {
  if (!STRICT || !schema || typeof schema !== 'object') return schema;
  const s = { ...schema };
  if (s.type === 'object') s.additionalProperties = false;
  if (s.properties) s.properties = Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, lock(v)]));
  if (s.items) s.items = lock(s.items);
  return s;
}

const ISSUE_AR = {
  cold_food: 'أكل بارد', taste_quality: 'طعم/جودة', portion_size: 'الكمية', hygiene: 'نظافة',
  wait_time: 'انتظار', delivery_delay: 'تأخير توصيل', order_accuracy: 'غلط بالطلب',
  packaging: 'تغليف', staff_behavior: 'تعامل الموظفين', price: 'السعر', ambience: 'الأجواء',
  other: 'أخرى', none: 'لا يوجد',
};

const issues = rows.filter((r) => r.is_issue);

function groupBy(list, keyFields) {
  const map = new Map();
  for (const r of list) {
    const key = keyFields.map((f) => r[f]).join(' | ');
    if (!map.has(key)) {
      const g = { count: 0, severity_sum: 0, review_ids: [], visit_hours: [], examples: [] };
      keyFields.forEach((f) => (g[f] = r[f]));
      map.set(key, g);
    }
    const g = map.get(key);
    g.count++;
    g.severity_sum += r.severity;
    g.review_ids.push(r.review_id);
    g.visit_hours.push(r.visit_hour);
    if (g.examples.length < 3) g.examples.push(r.summary);
  }
  return [...map.values()]
    .map((g) => ({ ...g, issue_ar: ISSUE_AR[g.issue_type], severity_avg: +(g.severity_sum / g.count).toFixed(1) }))
    .sort((a, b) => b.count - a.count || b.severity_sum - a.severity_sum);
}

const byDishShiftIssue = groupBy(issues, ['dish', 'shift', 'issue_type']);
const byIssueWeekPart = groupBy(issues, ['issue_type', 'week_part']);
const byDishIssue = groupBy(issues, ['dish', 'issue_type']);

const rated = rows.filter((r) => r.rating !== null);
const stats = {
  total: rows.length,
  issues: issues.length,
  negative: rows.filter((r) => r.is_negative).length,
  positive: rows.filter((r) => !r.is_issue).length,
  avg_rating: rated.length ? +(rated.reduce((s, r) => s + r.rating, 0) / rated.length).toFixed(1) : null,
  needs_review: rows.filter((r) => r.needs_review).length,
  tokens: rows.reduce((s, r) => s + (r.tokens || 0), 0),
};

const strip = ({ review_ids, severity_sum, ...g }) => g;
const llmInput = {
  week: rows[0] ? rows[0].week : null,
  stats,
  repeated_patterns_same_dish_same_shift: byDishShiftIssue.filter((g) => g.count >= 2).slice(0, 8).map(strip),
  issue_by_week_part: byIssueWeekPart.filter((g) => g.count >= 2).slice(0, 6).map(strip),
  dish_issue_all_shifts: byDishIssue.filter((g) => g.count >= 2).slice(0, 6).map(strip),
  critical_single_complaints: issues.filter((r) => r.severity >= 4)
    .map((r) => ({ dish: r.dish, shift: r.shift, issue_ar: ISSUE_AR[r.issue_type], severity: r.severity, summary: r.summary })),
};

const systemPrompt = `You are an operations consultant for "${cfg.restaurant_name}", a restaurant in Amman.
You get a weekly digest of customer complaints that was ALREADY counted by code. Write exactly 3 operational decisions for the manager and the head chef.

Rules:
- Decision 1 MUST address the first item of repeated_patterns_same_dish_same_shift (the strongest repeated pattern), if it exists.
- Decisions 2 and 3: the next strongest patterns. A critical single complaint (severity 5, hygiene/safety) outranks weaker repeated patterns.
- evidence: cite ONLY numbers present in the input (counts, shifts, visit_hours). Never invent numbers, staff names or causes stated as facts. A likely cause must be phrased as a hypothesis to check ("غالباً"، "تأكدوا إذا").
- action: one concrete, physical action that can be checked during the next shift (who checks what, when). Not "improve quality".
- If visit_hours show a time window, use it (e.g. between 18:00 and 21:30).
- Language: clear, simple Arabic (Jordanian-friendly), short sentences.
- headline: one line, format: "⚠️ <dish> بشفت <shift>: <count> شكاوى <issue>. الاقتراح: <short action>"`;

const decisionsBody = {
  model: cfg.model,
  temperature: 0.2,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: JSON.stringify(llmInput) },
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'weekly_decisions',
      strict: STRICT,
      schema: lock({
        type: 'object',
        required: ['headline', 'decisions'],
        properties: {
          headline: { type: 'string' },
          decisions: {
            type: 'array',
            items: {
              type: 'object',
              required: ['title', 'evidence', 'action', 'owner', 'priority'],
              properties: {
                title: { type: 'string' },
                evidence: { type: 'string' },
                action: { type: 'string' },
                owner: { type: 'string', enum: ['الشيف', 'مدير الصالة', 'مسؤول التوصيل', 'الإدارة'] },
                priority: { type: 'string', enum: ['عالية', 'متوسطة', 'منخفضة'] },
              },
            },
          },
        },
      }),
    },
  },
};

return [{ json: { stats, byDishShiftIssue, byIssueWeekPart, llmInput, decisionsBody } }];

// Build a mobile-friendly RTL HTML email (inline styles only: Gmail strips <style>).
const cfg = $('Config').first().json;
const agg = $('Aggregate patterns').first().json;
const rows = $('Parse classification').all().map((i) => i.json);
const res = $input.first().json;

let plan;
try {
  plan = JSON.parse(res.choices[0].message.content);
} catch (e) {
  throw new Error('Could not parse decisions from OpenAI: ' + JSON.stringify(res).slice(0, 300));
}
const decisions = (plan.decisions || []).slice(0, 3);

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const sevColor = (s) => (s >= 5 ? '#b42318' : s >= 3 ? '#c2410c' : '#a16207');
const prioColor = { 'عالية': '#b42318', 'متوسطة': '#c2410c', 'منخفضة': '#4b5563' };
const stars = (n) => (n ? '★'.repeat(n) + '☆'.repeat(5 - n) : '');
const week = rows[0] ? rows[0].week : { from: '', to: '' };
const { stats } = agg;

const FONT = "font-family:Tahoma,Arial,sans-serif;";
const card = 'background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;padding:14px 16px;margin:0 0 12px;';
const h2 = 'font-size:16px;margin:22px 0 10px;color:#111827;';

const statCell = (label, value, color) =>
  `<td style="width:25%;text-align:center;padding:10px 4px;background:#f9fafb;border-radius:8px;">
     <div style="font-size:20px;font-weight:bold;color:${color};">${esc(value)}</div>
     <div style="font-size:12px;color:#6b7280;">${label}</div></td>`;

const decisionsHtml = decisions.map((d, i) => `
  <div style="${card}border-right:4px solid ${prioColor[d.priority] || '#4b5563'};">
    <div style="font-size:12px;color:${prioColor[d.priority] || '#4b5563'};font-weight:bold;">قرار ${i + 1} · أولوية ${esc(d.priority)} · ${esc(d.owner)}</div>
    <div style="font-size:15px;font-weight:bold;margin:6px 0;color:#111827;">${esc(d.title)}</div>
    <div style="font-size:13px;color:#374151;margin:0 0 6px;">📊 ${esc(d.evidence)}</div>
    <div style="font-size:13px;color:#111827;background:#f0fdf4;border-radius:6px;padding:8px;">✅ ${esc(d.action)}</div>
  </div>`).join('');

const tableRow = (cells, header = false) =>
  `<tr>${cells.map((c) => `<${header ? 'th' : 'td'} style="padding:8px 6px;border-bottom:1px solid #e5e7eb;text-align:right;font-size:13px;${header ? 'color:#6b7280;font-weight:normal;' : ''}">${c}</${header ? 'th' : 'td'}>`).join('')}</tr>`;

const repeated = agg.byDishShiftIssue.filter((g) => g.count >= 2);
const singles = agg.byDishShiftIssue.filter((g) => g.count === 1).length;
const patternsHtml = repeated.length
  ? `<table role="presentation" style="width:100%;border-collapse:collapse;">
      ${tableRow(['الصحن · الشفت', 'المشكلة', 'العدد', 'الحدّة'], true)}
      ${repeated.map((g) => tableRow([
        `<b>${esc(g.dish)}</b><br><span style="color:#6b7280;font-size:12px;">${esc(g.shift)}</span>`,
        esc(g.issue_ar), `<b>${g.count}</b>`,
        `<span style="color:${sevColor(g.severity_avg)};">${g.severity_avg}/5</span>`])).join('')}
    </table>`
  : '<p style="font-size:13px;color:#6b7280;">ما في أنماط متكررة لنفس الصحن بنفس الشفت هالأسبوع.</p>';

const weekPart = agg.byIssueWeekPart.filter((g) => g.count >= 2);
const weekPartHtml = weekPart.length
  ? `<div style="font-size:13px;font-weight:bold;margin:16px 0 0;color:#111827;">📅 حسب الفترة (كل الأصناف)</div>
    <table role="presentation" style="width:100%;border-collapse:collapse;margin-top:4px;">
      ${tableRow(['المشكلة', 'الفترة', 'العدد'], true)}
      ${weekPart.map((g) => tableRow([esc(g.issue_ar), esc(g.week_part), `<b>${g.count}</b>`])).join('')}
    </table>` : '';

const negatives = rows.filter((r) => r.reply_draft).sort((a, b) => b.severity - a.severity);
const repliesHtml = negatives.map((r) => `
  <div style="${card}">
    <div style="font-size:12px;color:#6b7280;">${esc(r.review_id)} · ${esc(r.source)} · ${esc(r.shift)} · <span style="color:#d97706;">${stars(r.rating)}</span></div>
    <div style="font-size:13px;color:#374151;margin:6px 0;">«${esc(r.review_text.slice(0, 220))}»</div>
    <div style="font-size:12px;color:${sevColor(r.severity)};margin:0 0 6px;">${esc(r.summary)}</div>
    <div style="font-size:13px;color:#111827;background:#f3f4f6;border-radius:6px;padding:8px;" dir="auto">✍️ ${esc(r.reply_draft)}</div>
  </div>`).join('');

const sheetUrl = 'https://docs.google.com' + `/spreadsheets/d/${cfg.sheet_id}`;

const html = `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f3f4f6;">
<div dir="rtl" style="${FONT}max-width:600px;margin:0 auto;padding:16px;background:#f3f4f6;color:#111827;line-height:1.6;">
  <div style="font-size:13px;color:#6b7280;">${esc(cfg.restaurant_name)} · تقرير المراجعات الأسبوعي</div>
  <div style="font-size:12px;color:#9ca3af;margin-bottom:12px;">${esc(week.from)} ← ${esc(week.to)}</div>

  <div style="background:#fff7ed;border:1px solid #fdba74;border-radius:10px;padding:14px 16px;font-size:16px;font-weight:bold;color:#9a3412;">${esc(plan.headline)}</div>

  <table role="presentation" style="width:100%;border-collapse:separate;border-spacing:6px;margin:12px 0;"><tr>
    ${statCell('مراجعة', stats.total, '#111827')}
    ${statCell('فيها مشكلة', stats.issues, '#c2410c')}
    ${statCell('إيجابية', stats.positive, '#15803d')}
    ${statCell('معدّل التقييم', stats.avg_rating ?? '-', '#d97706')}
  </tr></table>

  <h2 style="${h2}">🎯 3 قرارات لهالأسبوع</h2>
  ${decisionsHtml}

  <h2 style="${h2}">🔁 الأنماط المتكررة (نفس الصحن · نفس الشفت)</h2>
  <div style="${card}">${patternsHtml}${weekPartHtml}
